from pathlib import Path
import json
P=Path(__file__).resolve().parent;packs={}
for gear in ['bare','helmet']:
 states=json.loads((P/(gear+'-manifest.json')).read_text(encoding='utf-8'))['states'];read=next(s for s in json.loads((P.parent/'bill-inspect-north-coherent-v1'/(gear+'-manifest.json')).read_text(encoding='utf-8'))['states'] if s['id']=='inspect-north');read['frameFiles']=['../bill-inspect-north-coherent-v1/'+f for f in read['frameFiles']];packs[gear]=[states[0],read,read,states[1]]
html='''<!doctype html><meta charset="utf-8"><title>Bill north reader transitions</title><style>body{font:16px system-ui;background:#152027;color:#e6eff1;margin:24px}p{max-width:80ch;color:#bdd0d2}select,button{font:inherit;padding:6px}canvas{display:block;margin-top:16px}a{color:#92d9dc}</style>
<h1>Bill — north reader transitions</h1><p>Draw the reader in front of the body, inspect, stow. Rear view naturally occludes the reader and gloves during the held pose. Exact standing idle/held endpoint joins and native selected north helmet. Candidate preview; live stage wiring remains pending.</p><p><a href="../bill-inspect-north-coherent-v1/">East standing inspection review</a></p>
<label>Gear <select id="gear"><option value="bare">Bare</option><option value="helmet">Helmet</option></select></label><label>Height <select id="size"><option>148</option><option selected>82</option><option>54</option></select></label><button id="play">Pause</button><canvas id="view" width="460" height="430"></canvas>
<script>const packs=DATA;let time=0,last=performance.now(),playing=true;gear.onchange=()=>time=0;play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play'};
Promise.all(Object.values(packs).flat().map(async s=>s.images=await Promise.all(s.frameFiles.map(f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f}))))).then(()=>{function draw(now){if(playing)time+=now-last;last=now;const images=packs[gear.value].flatMap(s=>s.images),durations=packs[gear.value].flatMap(s=>s.frameDurationsMs);let cursor=time%durations.reduce((a,b)=>a+b,0),index=0;for(let i=0;i<images.length;i++){index=i;if(cursor<durations[i])break;cursor-=durations[i]}const c=view.getContext('2d');c.fillStyle='#22343e';c.fillRect(0,0,460,215);c.fillStyle='#dae1e0';c.fillRect(0,215,460,215);const f=Number(size.value)/148;for(const y of [190,405])c.drawImage(images[index],230-128*f,y-224*f,256*f,256*f);requestAnimationFrame(draw)}requestAnimationFrame(draw)});</script>'''
(P/'index.html').write_text(html.replace('DATA',json.dumps(packs)),encoding='utf-8')
